    </main>
    <el-dialog v-model="createDialog" title="创建学习群" width="440px"><el-form label-position="top"><el-form-item label="群名称"><el-input v-model="group.title" placeholder="如：数据结构期末复习小组" /></el-form-item><el-form-item label="邀请学习伙伴"><el-select v-model="group.member_ids" multiple style="width:100%"><el-option v-for="f in friends" :key="f.id" :label="f.name + ' · ' + f.college" :value="f.id" /></el-select></el-form-item></el-form><template #footer><button class="primary" @click="createGroup">创建群聊</button></template></el-dialog>
    <el-dialog v-model="friendDialog" title="添加学习伙伴" width="440px"><el-input v-model="search" placeholder="输入姓名或学号搜索" @input="findUsers" /><div v-for="user in found" :key="user.id" class="found"><button class="avatar" @click="profile(user.id)"><AvatarBadge :value="user.avatar" :alt="user.name" /></button><div><b>{{ user.name }}</b><small>{{ user.student_id }} · {{ user.college }}</small></div><button @click="requestFriend(user.id)">添加</button></div></el-dialog>
    <el-dialog v-model="membersDialog" title="群成员与 Agent" width="520px"><div v-for="m in members" :key="m.id" class="member"><button class="avatar" @click="profile(m.id)"><AvatarBadge :value="m.avatar" :alt="m.name" /></button><div class="member-name"><button class="sender" @click="profile(m.id)">{{ m.name }}</button><small>{{ m.college }}</small></div><template v-if="m.agent_in_group"><button class="avatar agent-avatar" @click="profile(m.id, true)"><AvatarBadge :value="m.agent_avatar" :alt="m.agent_name" /></button><button class="sender" @click="profile(m.id, true)">{{ m.agent_name }}</button></template></div><div v-if="isOwner && !current.is_course_space" class="invite"><el-select v-model="inviteFriendId" placeholder="选择尚未入群的好友"><el-option v-for="f in availableFriends" :key="f.id" :label="f.name" :value="f.id" /></el-select><button class="primary" @click="inviteMember">邀请好友</button></div><button v-if="!myAgentInGroup && !current.is_course_space" class="primary agent-request" @click="requestMyAgent">邀请我的 Agent 入群（群主审批）</button></el-dialog>
    <el-dialog v-model="workspaceDialog" title="群学习协作空间" width="620px"><div class="workspace-panel"><p>只有你主动开启的摘要才会被小组协作 Agent 使用；不会共享私聊、完整计划、课表或个人 Agent 聊天。</p><div class="memory-sync-row"><span><b>群成果同步到“我的 Agent”</b><small>只同步协作结论摘要，不同步完整聊天记录</small></span><el-select v-model="memorySyncMode" size="small" @change="saveMemorySyncPreference"><el-option label="每次由我决定" value="ask" /><el-option label="自动保存新成果" value="auto" /><el-option label="不加入个人记忆" value="off" /></el-select></div><div class="workspace-head"><b>已加入的个人 Agent</b><small>{{ (workspace.agents || []).length }} 个 Agent 可参与群学习协作</small></div><div v-if="!(workspace.agents || []).length" class="muted">暂时没有 Agent 加入本群；可在“成员与 Agent”中申请邀请自己的 Agent。</div><div v-for="agent in workspace.agents || []" :key="agent.owner_id" class="group-agent-row"><AvatarBadge :value="agent.agent_avatar" :alt="agent.agent_name" /><span><b>{{ agent.agent_name }}</b><small>{{ agent.owner_name }} 的 Agent · {{ agent.auto_reply ? '实时参与已开启' : '仅 @ 时回答' }}</small></span><button v-if="isOwner || agent.owner_id === me.id" class="text" @click="removeGroupAgent(agent)">移出</button></div><div class="workspace-head discussion-head"><b>Agent 协作过程</b><button class="soft" @click="openDiscussion">发起讨论</button></div><div v-if="!discussionRuns.length" class="muted">暂时没有多 Agent 协作记录。</div><div v-for="run in discussionRuns.slice(0,3)" :key="run.id" class="discussion-run"><span><b>{{ run.topic }}</b><small>{{ run.mode === 'parallel' ? '并行分析' : '提案与质询' }} · {{ run.participants.map(item => item.agent_name).join('、') }}</small></span><em :class="run.status">{{ discussionStatus(run.status) }}</em><button v-if="['queued','running'].includes(run.status) && (run.initiator_id === me.id || isOwner)" class="text" @click="cancelDiscussion(run)">终止</button></div><hr><div class="consent-row"><span>共享我的薄弱知识点摘要</span><el-switch v-model="workspaceConsent.share_mastery" /></div><div class="consent-row"><span>共享我的待完成计划数量</span><el-switch v-model="workspaceConsent.share_plan_summary" /></div><button class="soft" @click="saveWorkspaceConsent">保存共享设置</button><hr><div class="workspace-head"><b>群任务</b><button class="soft" @click="facilitateGroup">✨ 生成协作建议</button></div><div v-for="task in workspace.tasks || []" :key="task.id" class="task-row"><div><b>{{ task.title }}</b><small>{{ task.assignee_name || '待认领' }} · {{ task.due_date || '无截止日期' }}<br>{{ task.description }}</small></div><button v-if="task.status !== 'done'" class="soft" @click="updateTask(task, 'doing')">进行中</button><button v-if="task.status !== 'done'" class="primary" @click="updateTask(task, 'done')">完成</button><em v-else>已完成</em></div><div class="task-create"><el-input v-model="newTask.title" placeholder="新建群任务" /><el-select v-model="newTask.assignee_id" clearable placeholder="负责人（可选）"><el-option v-for="m in workspace.members || []" :key="m.id" :label="m.name" :value="m.id" /></el-select><button class="primary" @click="createGroupTask">添加任务</button></div><hr><b>已授权学习摘要</b><div v-if="!(workspace.shared_learning || []).length" class="muted">暂无成员授权共享学习摘要。</div><div v-for="item in workspace.shared_learning || []" :key="item.user_id" class="shared-row"><b>{{ item.name }}</b><small v-if="item.weak_points?.length">薄弱重点：{{ item.weak_points.map(point => point.name).join('、') }}</small><small v-if="item.plan_summary !== undefined">待完成计划：{{ item.plan_summary }} 项</small></div><div v-if="workspace.latest_summary" class="summary-box"><b>最近一次群复习建议</b><p>{{ workspace.latest_summary.content }}</p><ul><li v-for="(item,index) in workspace.latest_summary.agenda" :key="index">{{ item }}</li></ul><button v-if="workspace.latest_summary.task_proposals?.length" class="primary" @click="importProposals(workspace.latest_summary.id)">将建议导入群任务</button></div></div></el-dialog>
    <el-dialog v-model="discussionDialog" title="发起多 Agent 学习讨论" width="540px"><div class="discussion-dialog"><p>只有已获群主批准入群的 Agent 可以参与。发起者使用自己的模型 API Key 支付本次调用；系统最多运行 3 个 Agent、两轮讨论，并可随时终止。</p><el-form label-position="top"><el-form-item label="选择参与讨论的 Agent（2～3 个）"><el-select v-model="discussionForm.agent_owner_ids" multiple :multiple-limit="3" style="width:100%"><el-option v-for="agent in groupAgents" :key="agent.id" :label="agent.agent_name + ' · ' + agent.name" :value="agent.id" /></el-select></el-form-item><el-form-item label="协作方式"><el-radio-group v-model="discussionForm.mode"><el-radio value="debate">提案 → 质询 → 修订 → 总结</el-radio><el-radio value="parallel">分别分析 → 汇总</el-radio></el-radio-group></el-form-item><el-form-item label="讨论主题"><el-input v-model="discussionForm.topic" type="textarea" :rows="4" maxlength="2000" show-word-limit placeholder="例如：请比较 AVL 树和红黑树，并给出期末复习时应优先掌握的内容。" /></el-form-item></el-form><div v-if="activeDiscussion" class="discussion-active">当前协作正在进行：{{ activeDiscussion.topic }} <button class="text" @click="cancelDiscussion(activeDiscussion)">终止</button></div></div><template #footer><button class="soft" @click="discussionDialog = false">取消</button><button class="primary" :disabled="discussionLoading" @click="startDiscussion">{{ discussionLoading ? '正在启动…' : '启动协作' }}</button></template></el-dialog>
    <el-dialog v-model="agentRequestsDialog" title="等待审批的 Agent" width="470px"><div v-if="!agentRequests.length" class="empty">暂无待审批申请。</div><div v-for="r in agentRequests" :key="r.id" class="request-line"><span><AvatarBadge class="request-agent-avatar" :value="r.agent_avatar" :alt="r.agent_name" /> <b>{{ r.agent_name }}</b> · {{ r.name }} 的 Agent</span><span><button class="soft" @click="handleAgentRequest(r.id, 'reject')">拒绝</button><button class="primary" @click="handleAgentRequest(r.id, 'approve')">同意</button></span></div></el-dialog>
  </div>
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import AppNav from '../components/AppNav.vue'
import AvatarBadge from '../components/AvatarBadge.vue'
import FriendRemarkManager from '../components/FriendRemarkManager.vue'
import GroupManagementDialog from '../components/GroupManagementDialog.vue'
import { api, post } from '../utils/api'
import { renderLearningMarkdown, stripAgentDisplayPrefix } from '../utils/learningMarkdown'
const router = useRouter(), route = useRoute(); const conversations = ref([]), friends = ref([]), teachers = ref([]), requests = ref([]), friendAgentRequests = ref([]), messages = ref([]), members = ref([]), agentRequests = ref([]); const currentId = ref(null), input = ref(''), createDialog = ref(false), friendDialog = ref(false), membersDialog = ref(false), agentRequestsDialog = ref(false), search = ref(''), found = ref([]), inviteFriendId = ref(null), group = ref({ title: '', member_ids: [] }), messageBox = ref(null), agentBarCollapsed = ref(false); let timer
const workspaceDialog = ref(false), workspace = ref({ tasks: [], members: [], shared_learning: [], latest_summary: null }), workspaceConsent = ref({ share_mastery: false, share_plan_summary: false }), memorySyncMode = ref('ask'), newTask = ref({ title: '', assignee_id: null })
const discussionDialog = ref(false), discussionRuns = ref([]), discussionLoading = ref(false), discussionForm = ref({ agent_owner_ids: [], topic: '', mode: 'debate' })
const agentSessions = ref([])
const me = computed(() => JSON.parse(localStorage.getItem('user') || '{}')); const current = computed(() => conversations.value.find(x => x.id === currentId.value)); const isOwner = computed(() => current.value?.owner_id === me.value.id); const meMember = computed(() => members.value.find(m => m.id === me.value.id)); const myAgentInGroup = computed(() => Boolean(meMember.value?.agent_in_group)); const groupAgents = computed(() => members.value.filter(m => m.agent_in_group)); const availableFriends = computed(() => friends.value.filter(f => !members.value.some(m => m.id === f.id))); const activeDiscussion = computed(() => discussionRuns.value.find(item => ['queued', 'running'].includes(item.status))); const activeAgentSession = computed(() => agentSessions.value.find(item => ['queued', 'active', 'stopping', 'finalizing'].includes(item.status)))
watch(friends, list => list.forEach(friend => { friend.real_name = friend.name; if (friend.remark) friend.name = friend.remark }), { deep: false })
const formatTime = value => {
  if (!value) return ''
  const text = String(value).trim()
  const date = new Date(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(text) ? `${text.replace(' ', 'T')}Z` : text)
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false })
}
async function load () { const data=await Promise.all([api('/conversations'), api('/friends'), api('/friend-requests'), api('/friend-agent/requests'), me.value.role==='student'?api('/teachers'):Promise.resolve([])]);[conversations.value, friends.value, requests.value, friendAgentRequests.value, teachers.value]=data; const requestedId = Number(route.query.conversation_id || 0); const target = requestedId && conversations.value.some(item => item.id === requestedId) ? requestedId : conversations.value[0]?.id; if (target && (!currentId.value || requestedId)) await open(target) }
async function handleConversationRemoved () {
  currentId.value = null
  messages.value = []
  members.value = []
  agentRequests.value = []
  discussionRuns.value = []
  agentSessions.value = []
  try { await load() } catch (error) { ElMessage.error(error.message) }
}
async function open (id) { currentId.value = id; agentBarCollapsed.value = false; await refreshCurrent(); const conversation = conversations.value.find(item => item.id === id); if (conversation) conversation.unread_count = 0; await nextTick(); if (messageBox.value) messageBox.value.scrollTop = messageBox.value.scrollHeight }
async function refreshCurrent () { if (!currentId.value) return; messages.value = await api(`/conversations/${currentId.value}/messages`); if (current.value?.type === 'group') { members.value = await api(`/conversations/${currentId.value}/members`); agentRequests.value = isOwner.value ? await api(`/conversations/${currentId.value}/agent-requests`) : []; await Promise.all([refreshDiscussionRuns(), refreshAgentSessions()]) } else { members.value = []; discussionRuns.value = []; agentSessions.value = [] } }
async function send () { const content = input.value.trim(); if (!content) return; const targets = current.value?.type === 'group' ? groupAgents.value.filter(agent => content.includes(`@${agent.agent_name}`)) : []; try { await post(`/conversations/${currentId.value}/messages`, { content }); input.value = ''; if (targets.length >= 2 && !activeAgentSession.value) await startAgentSession({ agent_owner_ids: targets.map(agent => agent.id), topic: content }, true); else if (targets.length === 1 && !activeAgentSession.value) await post(`/conversations/${currentId.value}/agent-ask`, { agent_owner_id: targets[0].id, question: content }); await refreshCurrent(); await nextTick(); if (messageBox.value) messageBox.value.scrollTop = messageBox.value.scrollHeight; await load() } catch (e) { ElMessage.error(e.message) } }
async function privateChat (friendId) { try { const data = await post('/conversations/private', { friend_id: friendId }); await load(); await open(data.id) } catch (e) { ElMessage.error(e.message) } }
async function createGroup () { try { const data = await post('/conversations', group.value); createDialog.value = false; group.value = { title: '', member_ids: [] }; await load(); await open(data.id) } catch (e) { ElMessage.error(e.message) } }
async function findUsers () { found.value = search.value.trim() ? await api(`/users/search?q=${encodeURIComponent(search.value)}`) : [] }
async function requestFriend (id) { try { await post('/friend-requests', { user_id: id }); ElMessage.success('好友申请已发送') } catch (e) { ElMessage.error(e.message) } }
async function accept (id) { try { await post(`/friend-requests/${id}/accept`, {}); await load(); ElMessage.success('已成为好友') } catch (e) { ElMessage.error(e.message) } }
async function friendAgent (ownerId) { try { const state = await api(`/friend-agents/${ownerId}/access`); if (state.status === 'approved') return router.push(`/friend-agent/${ownerId}`); if (state.status === 'pending') return ElMessage.info('已申请访问，等待好友同意'); const data = await post(`/friend-agents/${ownerId}/access`, {}); ElMessage.success(data.status === 'approved' ? '已获得授权' : '已提交 Agent 访问申请') } catch (e) { ElMessage.error(e.message) } }
async function decideFriendAgent (id, action) { try { const data = await api(`/friend-agent/requests/${id}`, { method: 'PATCH', body: JSON.stringify({ action }) }); ElMessage.success(data.message); await load() } catch (e) { ElMessage.error(e.message) } }
async function inviteMember () { try { await post(`/conversations/${currentId.value}/members`, { user_id: inviteFriendId.value }); inviteFriendId.value = null; await refreshCurrent(); await load(); ElMessage.success('已邀请好友入群') } catch (e) { ElMessage.error(e.message) } }
async function requestMyAgent () { try { await post(`/conversations/${currentId.value}/agent-requests`, {}); await refreshCurrent(); ElMessage.success('已提交申请，等待群主审批') } catch (e) { ElMessage.error(e.message) } }
async function handleAgentRequest (id, action) { try { await api(`/conversations/${currentId.value}/agent-requests/${id}`, { method: 'PATCH', body: JSON.stringify({ action }) }); await refreshCurrent(); ElMessage.success(action === 'approve' ? '已同意 Agent 入群' : '已拒绝申请') } catch (e) { ElMessage.error(e.message) } }
async function toggleMyAgent (autoReply) { try { const data = await api(`/conversations/${currentId.value}/my-agent`, { method: 'PATCH', body: JSON.stringify({ auto_reply: autoReply }) }); ElMessage.success(data.message); await refreshCurrent() } catch (e) { ElMessage.error(e.message) } }
const discussionStatus = status => ({ queued: '排队中', running: '协作中', completed: '已完成', cancelled: '已终止', failed: '失败' }[status] || status)
async function refreshDiscussionRuns () { if (!currentId.value || current.value?.type !== 'group') return; discussionRuns.value = await api(`/conversations/${currentId.value}/agent-discussions`) }
async function refreshAgentSessions () { if (!currentId.value || current.value?.type !== 'group') return; agentSessions.value = await api(`/conversations/${currentId.value}/agent-sessions`) }
async function startAgentSession (form, quiet = false) { const data = await post(`/conversations/${currentId.value}/agent-sessions`, form); if (!quiet) ElMessage.success(data.message); agentSessions.value = [data.session, ...agentSessions.value.filter(item => item.id !== data.session.id)]; return data }
async function stopAgentSession (session) { try { const data = await post(`/conversations/${currentId.value}/agent-sessions/${session.id}/stop`, {}); ElMessage.success(data.message); await refreshAgentSessions() } catch (e) { ElMessage.error(e.message) } }
async function openDiscussion () { if (current.value?.type !== 'group') return; await refreshDiscussionRuns(); discussionForm.value = { agent_owner_ids: groupAgents.value.slice(0, 2).map(agent => agent.id), topic: '', mode: 'debate' }; discussionDialog.value = true }
async function startDiscussionWith (form, quiet = false) { const data = await post(`/conversations/${currentId.value}/agent-discussions`, form); if (!quiet) ElMessage.success(data.message); discussionRuns.value = [data.run, ...discussionRuns.value.filter(item => item.id !== data.run.id)]; return data }
async function startDiscussion () { if (discussionLoading.value) return; if (discussionForm.value.agent_owner_ids.length < 2) return ElMessage.warning('请至少选择 2 个 Agent'); if (!discussionForm.value.topic.trim()) return ElMessage.warning('请填写讨论主题'); discussionLoading.value = true; try { await startDiscussionWith({ ...discussionForm.value, topic: discussionForm.value.topic.trim() }); discussionDialog.value = false; await refreshCurrent() } catch (e) { ElMessage.error(e.message) } finally { discussionLoading.value = false } }
async function cancelDiscussion (run) { try { const data = await post(`/conversations/${currentId.value}/agent-discussions/${run.id}/cancel`, {}); ElMessage.success(data.message); await refreshDiscussionRuns() } catch (e) { ElMessage.error(e.message) } }
async function removeGroupAgent (agent) { try { await api(`/conversations/${currentId.value}/group-agents/${agent.owner_id}`, { method: 'DELETE' }); ElMessage.success('已移出该 Agent'); await refreshCurrent(); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function refreshWorkspace () { if (!currentId.value) return; workspace.value = await api(`/conversations/${currentId.value}/workspace`); workspaceConsent.value = { ...workspace.value.my_consent } }
async function openWorkspace () { try { await Promise.all([refreshWorkspace(), api(`/agent/memory-sync-preferences?conversation_id=${currentId.value}`).then(data => { memorySyncMode.value = data.mode || 'ask' })]); workspaceDialog.value = true } catch (e) { ElMessage.error(e.message) } }
async function saveMemorySyncPreference () { try { const data = await api('/agent/memory-sync-preferences', { method: 'PUT', body: JSON.stringify({ conversation_id: currentId.value, mode: memorySyncMode.value }) }); ElMessage.success(data.message) } catch (e) { ElMessage.error(e.message) } }
async function saveWorkspaceConsent () { try { const data = await api(`/conversations/${currentId.value}/learning-consent`, { method: 'PATCH', body: JSON.stringify(workspaceConsent.value) }); ElMessage.success(data.message); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function createGroupTask () { const title = newTask.value.title.trim(); if (!title) return ElMessage.warning('请填写群任务标题'); try { const data = await post(`/conversations/${currentId.value}/tasks`, { title, assignee_id: newTask.value.assignee_id }); ElMessage.success(data.message); newTask.value = { title: '', assignee_id: null }; await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function updateTask (task, status) { try { const data = await api(`/conversations/${currentId.value}/tasks/${task.id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); ElMessage.success(data.message); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function facilitateGroup () { try { const data = await post(`/conversations/${currentId.value}/facilitate`, {}); ElMessage.success(data.message); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function importProposals (summaryId) { try { const data = await post(`/conversations/${currentId.value}/summaries/${summaryId}/import-tasks`, {}); ElMessage.success(data.message); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
function profile (id, agent = false) { router.push({ path: `/profile/${id}`, query: agent ? { agent: '1' } : {} }) }
async function downloadGroupAttachment (file) { try { const response = await fetch(file.download_url, { headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` } }); if (!response.ok) throw new Error('下载失败'); const url = URL.createObjectURL(await response.blob()), anchor = document.createElement('a'); anchor.href = url; anchor.download = file.file_name; anchor.click(); URL.revokeObjectURL(url) } catch (e) { ElMessage.error(e.message) } }
onMounted(async () => { try { await load(); timer = setInterval(async () => { try { await refreshCurrent(); await load() } catch {} }, 4000) } catch (e) { ElMessage.error(e.message) } }); onBeforeUnmount(() => clearInterval(timer))
</script>
